	}
	ref, err := s.repo.Reference(refName, true)
	if err == nil {
		return ref, nil
	}
	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
		return nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
	}
